import{_ as r,I as s,c as n,o as t,a3 as a,b as E,w as c,a as l,J as i,a4 as A,c1 as d,c2 as h,c3 as p,c4 as S,c5 as B,c6 as m}from"./chunks/framework.MI-M1z4O.js";const T=JSON.parse('{"title":"SyncWatch 概要 — 全社セキュリティ脅威収集・コンパイル・配信エージェント","description":"グローバルなセキュリティ脅威フィードと診断ドキュメントを単一ハブに収集・正規化し、SyncVerse (VerseAuditPack) および SyncAPIM (ApimDefensePack) へリアルタイムにコンパイル・配信する全社セキュリティ観測所 SyncWatch の技術ドキュメントです。","frontmatter":{"title":"SyncWatch 概要 — 全社セキュリティ脅威収集・コンパイル・配信エージェント","description":"グローバルなセキュリティ脅威フィードと診断ドキュメントを単一ハブに収集・正規化し、SyncVerse (VerseAuditPack) および SyncAPIM (ApimDefensePack) へリアルタイムにコンパイル・配信する全社セキュリティ観測所 SyncWatch の技術ドキュメントです。","sidebarTitle":"概要","sort":1,"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/syncwatch/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/syncwatch/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/syncwatch/"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/syncwatch/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/syncwatch/"}]]},"headers":[],"relativePath":"ja/syncwatch/index.md","filePath":"ja/syncwatch/index.md","lastUpdated":1795293539000}'),g={name:"ja/syncwatch/index.md"};function y(D,e,_,u,P,f){const o=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="syncwatch-概要-ai-security-threat-intelligence-rule-compiler-agent" tabindex="-1">SyncWatch 概要 (AI Security Threat Intelligence &amp; Rule Compiler Agent) <a class="header-anchor" href="#syncwatch-概要-ai-security-threat-intelligence-rule-compiler-agent" aria-label="Permalink to “SyncWatch 概要 (AI Security Threat Intelligence &amp; Rule Compiler Agent)”">​</a></h1><blockquote><p><strong>非開発者・導入検討のご案内</strong>: 分かりやすい製品紹介は <a href="https://watch.empasy.io/ja/" target="_blank" rel="noopener">SyncWatch 製品ホームページ (watch.empasy.io)</a> で、インストール不要の画面体験は <a href="https://sync.empasy.io/ja/products/sync-watch#demo" target="_blank" rel="noopener">統合デモポータル</a> でご利用いただけます。また、紹介資料・提案書 PDF は <a href="/ja/proposals/">提案書資料室</a> からダウンロードできます。</p></blockquote><p><strong>SyncWatch (<code>SYNC_WATCH</code>, <code>com.empasy.sync.watch</code>)</strong> は、<strong>8 大グローバル脅威フィード (OSV.dev、GitHub GHSA、NVD CVE、CISA KEV、Nuclei、OWASP CRS、MITRE ATT&amp;CK、KISA)</strong> と企業内部のセキュリティ診断ドキュメントを単一ハブへ収集・正規化し、<strong>SyncVerse</strong> にはコード・依存関係・ペネトレーションテストのセキュリティ点検パック (<strong><code>VerseAuditPack</code></strong>) を、<strong>SyncAPIM</strong> にはランタイム攻撃パターン防御パック (<strong><code>ApimDefensePack</code></strong>) をリアルタイムにコンパイル・配信する <strong>全社セキュリティ観測所 (Security Threat Observatory &amp; Dual Rule Compiler)</strong> です。</p><hr><h2 id="_1-主要諸元および接続情報" tabindex="-1">1. 主要諸元および接続情報 <a class="header-anchor" href="#_1-主要諸元および接続情報" aria-label="Permalink to “1. 主要諸元および接続情報”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">標準仕様</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>エージェント識別コード</strong></td><td style="text-align:left;"><code>SYNC_WATCH</code> (<code>sync-watch</code>)</td></tr><tr><td style="text-align:left;"><strong>Maven 座標系</strong></td><td style="text-align:left;"><code>com.empasy.sync.watch:sync-watch-server</code> (Spring Boot 4.0.x, JDK 25)</td></tr><tr><td style="text-align:left;"><strong>標準 API Prefix</strong></td><td style="text-align:left;"><code>/api/v1/watch/*</code> (権限 API: <code>/api/v1/watch/sys/permission/getUserPermissionByToken</code>)</td></tr><tr><td style="text-align:left;"><strong>Admin 管理コンソール</strong></td><td style="text-align:left;">ローカル: <code>http://localhost:3107</code> / クラウド: <code>https://watch-admin.empasy.io</code></td></tr><tr><td style="text-align:left;"><strong>バックエンド API &amp; ホームページ</strong></td><td style="text-align:left;">ローカル: <code>http://localhost:18087/api/v1/watch</code> / クラウド: <code>https://watch.empasy.io</code></td></tr><tr><td style="text-align:left;"><strong>データベース</strong></td><td style="text-align:left;">PostgreSQL 18.6 (<code>sync_watch</code>、6 大ドメインテーブル <code>watch_*</code>)</td></tr></tbody></table><hr><h2 id="_2-3-角自律-devsecops-セキュリティアーキテクチャ-triad-autonomous-devsecops" tabindex="-1">2. 3 角自律 DevSecOps セキュリティアーキテクチャ (Triad Autonomous DevSecOps) <a class="header-anchor" href="#_2-3-角自律-devsecops-セキュリティアーキテクチャ-triad-autonomous-devsecops" aria-label="Permalink to “2. 3 角自律 DevSecOps セキュリティアーキテクチャ (Triad Autonomous DevSecOps)”">​</a></h2><p>SyncSeries は、新たなゼロデイ脆弱性やセキュリティ勧告が公開された際、セキュリティ担当者の手動分析や正規表現の作成によって生じる防御空白期間 (Window of Exposure) を解消するため、<strong>SyncWatch → SyncVerse → SyncAPIM</strong> へと連携する 3 角自律 DevSecOps ループを運用しています。</p>',9)),(t(),E(A,null,{default:c(()=>[i(o,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Feeds%5B%228%20%E5%A4%A7%E3%82%B0%E3%83%AD%E3%83%BC%E3%83%90%E3%83%AB%E8%84%85%E5%A8%81%E3%83%95%E3%82%A3%E3%83%BC%E3%83%89%20%26%20%E8%A8%BA%E6%96%AD%E3%83%89%E3%82%AD%E3%83%A5%E3%83%A1%E3%83%B3%E3%83%88%22%5D%0A%20%20%20%20%20%20%20%20F1%5B%22OSV.dev%20%2F%20GitHub%20GHSA%22%5D%0A%20%20%20%20%20%20%20%20F2%5B%22NVD%20CVE%20%2F%20CISA%20KEV%22%5D%0A%20%20%20%20%20%20%20%20F3%5B%22Nuclei%20%2F%20OWASP%20CRS%20%2F%20MITRE%20ATT%26CK%20%2F%20KISA%22%5D%0A%20%20%20%20%20%20%20%20F4%5B%22%E3%82%BB%E3%82%AD%E3%83%A5%E3%83%AA%E3%83%86%E3%82%A3%E8%A8%BA%E6%96%AD%E3%83%AC%E3%83%9D%E3%83%BC%E3%83%88%20(PDF%2FMD)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Watch%5B%221.%20SyncWatch%20(%E5%8F%8E%E9%9B%86%E3%83%BB%E6%AD%A3%E8%A6%8F%E5%8C%96%E3%83%BB%E3%83%87%E3%83%A5%E3%82%A2%E3%83%AB%E3%82%B3%E3%83%B3%E3%83%91%E3%82%A4%E3%83%AB)%22%5D%0A%20%20%20%20%20%20%20%20W1%5B%225%20%E6%AE%B5%E9%9A%8E%20SSRF%20%E3%82%AC%E3%83%BC%E3%83%89%E3%82%B3%E3%83%AC%E3%82%AF%E3%82%BF%E3%83%BC%22%5D%0A%20%20%20%20%20%20%20%20W2%5B%22%E6%AD%A3%E8%A6%8F%E5%8C%96%E3%82%BB%E3%82%AD%E3%83%A5%E3%83%AA%E3%83%86%E3%82%A3%E5%8F%B0%E5%B8%B3%20(watch_security_advisory)%22%5D%0A%20%20%20%20%20%20%20%20W3%5B%22WatchRuleCompilerService%20%26%20%E7%8B%AC%E8%87%AA%E3%82%B5%E3%83%B3%E3%83%89%E3%83%9C%E3%83%83%E3%82%AF%E3%82%B9%E6%A4%9C%E8%A8%BC%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Verse%5B%222.%20SyncVerse%20(Shift-Left%20%E3%82%B3%E3%83%BC%E3%83%89%E3%82%BB%E3%82%AD%E3%83%A5%E3%83%AA%E3%83%86%E3%82%A3%E7%9B%A3%E6%9F%BB)%22%5D%0A%20%20%20%20%20%20%20%20V1%5B%22VerseAuditPack%20%E5%8F%97%E4%BF%A1%20(SCA%20%2F%20SAST%20%2F%20DAST)%22%5D%0A%20%20%20%20%20%20%20%20V2%5B%22%E5%85%A8%E7%A4%BE%20Git%20%E3%83%AA%E3%83%9D%E3%82%B8%E3%83%88%E3%83%AA%E8%84%86%E5%BC%B1%E6%80%A7%E3%82%B9%E3%82%AD%E3%83%A3%E3%83%B3%22%5D%0A%20%20%20%20%20%20%20%20V3%5B%22%E8%87%AA%E5%8B%95%E3%82%BB%E3%82%AD%E3%83%A5%E3%83%AA%E3%83%86%E3%82%A3%E3%83%91%E3%83%83%E3%83%81%20PR%20%E7%94%9F%E6%88%90%20%26%20HITL%20%E6%89%BF%E8%AA%8D%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Apim%5B%223.%20SyncAPIM%20(Shift-Right%20%E3%83%A9%E3%83%B3%E3%82%BF%E3%82%A4%E3%83%A0%E4%BB%AE%E6%83%B3%E3%83%91%E3%83%83%E3%83%81)%22%5D%0A%20%20%20%20%20%20%20%20A1%5B%22ApimDefensePack%20%E5%8F%97%E4%BF%A1%20(%E6%A7%8B%E6%96%87%E3%83%95%E3%82%A3%E3%83%B3%E3%82%AC%E3%83%BC%E3%83%97%E3%83%AA%E3%83%B3%E3%83%88%20%2F%20SpEL)%22%5D%0A%20%20%20%20%20%20%20%20A2%5B%22SqlXssLexicalTokenizer%20%26%20SandboxedDefenseEvaluator%22%5D%0A%20%20%20%20%20%20%20%20A3%5B%22%E7%84%A1%E5%81%9C%E6%AD%A2%E3%83%94%E3%83%B3%E3%83%9D%E3%82%A4%E3%83%B3%E3%83%88%E4%BB%AE%E6%83%B3%E3%83%91%E3%83%83%E3%83%81%20%26%20%E3%82%AB%E3%83%BC%E3%83%8D%E3%83%AB%20eBPF%20%E9%81%AE%E6%96%AD%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Feeds%20--%3E%20W1%20--%3E%20W2%20--%3E%20W3%0A%20%20%20%20W3%20--%3E%7C%22VerseAuditPack%20%E9%85%8D%E4%BF%A1%22%7C%20V1%20--%3E%20V2%20--%3E%20V3%0A%20%20%20%20W3%20--%3E%7C%22ApimDefensePack%20%E9%85%8D%E4%BF%A1%22%7C%20A1%20--%3E%20A2%20--%3E%20A3%0A%20%20%20%20V3%20-.-%3E%7C%22%E9%81%A9%E7%94%A8%E3%83%95%E3%82%A3%E3%83%BC%E3%83%89%E3%83%90%E3%83%83%E3%82%AF%22%7C%20W3%0A%20%20%20%20A3%20-.-%3E%7C%22%E9%81%AE%E6%96%AD%E3%83%95%E3%82%A3%E3%83%BC%E3%83%89%E3%83%90%E3%83%83%E3%82%AF%22%7C%20W3%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<ol><li><strong>SyncWatch (Threat Ingestion &amp; Dual Rule Compilation)</strong>: <ul><li>外部脅威フィードやセキュリティ診断ドキュメントを収集し、CWE、MITRE ATT&amp;CK、エコシステム (<code>MAVEN</code>、<code>NPM</code>、<code>PYPI</code>、<code>DOCKER</code> など) 基準で正規化します。</li><li>単一のセキュリティ課題台帳から、開発段階の点検用 <code>VerseAuditPack</code> と本番ゲートウェイ防御用 <code>ApimDefensePack</code> を同時にコンパイルし、隔離サンドボックスで攻撃サンプル (Positive) と正常サンプル (Negative) を照合検証します。</li></ul></li><li><strong>SyncVerse (Shift-Left Code Security Audit &amp; Auto-Patch PR)</strong>: <ul><li>受信した <code>VerseAuditPack</code> に基づき、全社マイクロサービスリポジトリの依存関係バージョン (<code>SCA_DEPENDENCY</code>)、ソースコード脆弱性パターン (<code>SAST_CODE</code>)、サンドボックスエンドポイントのペネトレーションテスト (<code>DAST_PENTEST</code>) を自動実行し、パッチ Pull Request を生成します。</li></ul></li><li><strong>SyncAPIM (Shift-Right Runtime Defense &amp; Pinpoint Virtual Patching)</strong>: <ul><li>コードパッチが本番環境にデプロイされる前であっても、受信した <code>ApimDefensePack</code> を <code>SqlXssLexicalTokenizer</code> (構文トークンフィンガープリント分析器) および <code>SandboxedDefenseEvaluator</code> (ピンポイント仮想パッチ評価器) に無停止ホットスワップで適用し、カーネル eBPF で攻撃元を即座に遮断します。</li></ul></li></ol><hr><h2 id="実稼働画面および主要ワークフロー" tabindex="-1">実稼働画面および主要ワークフロー <a class="header-anchor" href="#実稼働画面および主要ワークフロー" aria-label="Permalink to “実稼働画面および主要ワークフロー”">​</a></h2><h3 id="_1-グローバルセキュリティ脅威インテリジェンス収集および観測ダッシュボード" tabindex="-1">1. グローバルセキュリティ脅威インテリジェンス収集および観測ダッシュボード <a class="header-anchor" href="#_1-グローバルセキュリティ脅威インテリジェンス収集および観測ダッシュボード" aria-label="Permalink to “1. グローバルセキュリティ脅威インテリジェンス収集および観測ダッシュボード”">​</a></h3><p>OSV.dev、GitHub GHSA、NVD CVE、CISA KEV、Nuclei、OWASP CRS、MITRE ATT&amp;CK、KISA など 8 大グローバル脅威フィードのリアルタイム収集状況と深刻度分布を統合管制します。</p><p><img src="'+d+'" alt="SyncWatch グローバルセキュリティ脅威観測ダッシュボード" loading="lazy"></p><h3 id="_2-8-大公認セキュリティフィード収集チャネルおよび接続診断" tabindex="-1">2. 8 大公認セキュリティフィード収集チャネルおよび接続診断 <a class="header-anchor" href="#_2-8-大公認セキュリティフィード収集チャネルおよび接続診断" aria-label="Permalink to “2. 8 大公認セキュリティフィード収集チャネルおよび接続診断”">​</a></h3><p>外部セキュリティフィード収集チャネルのポーリングスケジュール、5 段階 SSRF 防御ガード接続診断、即時同期および収集バッチ実行状態を管理します。</p><p><img src="'+h+'" alt="SyncWatch 外部セキュリティフィード収集チャネル管理" loading="lazy"></p><h3 id="_3-正規化セキュリティ勧告台帳および全社-sbom-マッチング分析" tabindex="-1">3. 正規化セキュリティ勧告台帳および全社 SBOM マッチング分析 <a class="header-anchor" href="#_3-正規化セキュリティ勧告台帳および全社-sbom-マッチング分析" aria-label="Permalink to “3. 正規化セキュリティ勧告台帳および全社 SBOM マッチング分析”">​</a></h3><p>多様なフォーマットの外部セキュリティ勧告や診断ドキュメントを単一標準スキーマへ正規化し、影響を受けるパッケージエコシステムと全社 SBOM 影響度を分析します。</p><p><img src="'+p+'" alt="SyncWatch 正規化セキュリティ勧告台帳" loading="lazy"></p><h3 id="_4-エコシステム別脆弱パッケージおよびコードセキュリティ点検基準" tabindex="-1">4. エコシステム別脆弱パッケージおよびコードセキュリティ点検基準 <a class="header-anchor" href="#_4-エコシステム別脆弱パッケージおよびコードセキュリティ点検基準" aria-label="Permalink to “4. エコシステム別脆弱パッケージおよびコードセキュリティ点検基準”">​</a></h3><p>開発管制塔に供給される依存関係バージョン範囲 (SCA)、静的コードパターン (SAST)、動的ランタイムプローブ (DAST) 点検基準および脆弱シンボル仕様を管理します。</p><p><img src="'+S+'" alt="SyncWatch 脆弱パッケージおよびコードセキュリティ点検基準" loading="lazy"></p><h3 id="_5-ランタイム攻撃パターンおよびサンドボックス正・誤検知検証" tabindex="-1">5. ランタイム攻撃パターンおよびサンドボックス正・誤検知検証 <a class="header-anchor" href="#_5-ランタイム攻撃パターンおよびサンドボックス正・誤検知検証" aria-label="Permalink to “5. ランタイム攻撃パターンおよびサンドボックス正・誤検知検証”">​</a></h3><p>API セキュリティゲートウェイに供給される HTTP 検査位置、検知正規表現、防御条件式およびサンドボックス誤検知ゼロ検証 (TP 100%、FP 0%) 結果を管理します。</p><p><img src="'+B+'" alt="SyncWatch ランタイム攻撃パターンおよびサンドボックス検証" loading="lazy"></p><h3 id="_6-フィード収集・パース実行ログおよび全社配信履歴" tabindex="-1">6. フィード収集・パース実行ログおよび全社配信履歴 <a class="header-anchor" href="#_6-フィード収集・パース実行ログおよび全社配信履歴" aria-label="Permalink to “6. フィード収集・パース実行ログおよび全社配信履歴”">​</a></h3><p>収集・コンパイル・サンドボックス検証バッチの実行ログと、購読サービス向けの脅威情報ブロードキャスト提供履歴を透明に追跡します。</p><p><img src="'+m+'" alt="SyncWatch フィード収集実行ログおよび全社配信履歴" loading="lazy"></p><hr><h2 id="_3-ドキュメント構成のご案内" tabindex="-1">3. ドキュメント構成のご案内 <a class="header-anchor" href="#_3-ドキュメント構成のご案内" aria-label="Permalink to “3. ドキュメント構成のご案内”">​</a></h2><ul><li><strong><a href="./architecture">アーキテクチャおよびデュアルルールコンパイラ</a></strong>: 8 大グローバル脅威フィード収集チャネル、5 段階 SSRF 防御ガード、<code>WatchRuleCompilerService</code> デュアルルールコンパイルおよび独自サンドボックス検証メカニズムを説明します。</li><li><strong><a href="./devsecops-protocol">SyncVerse &amp; SyncAPIM 連携プロトコル</a></strong>: <code>VerseAuditPack</code> および <code>ApimDefensePack</code> のデータ契約とリアルタイムブロードキャスト・フィードバックプロトコルを解説します。</li><li><strong><a href="./api-and-schema">DB スキーマおよび REST/MCP API 仕様</a></strong>: 6 大 <code>watch_*</code> テーブルの DDL 規格と <code>/api/v1/watch/*</code> REST API および MCP ツールをご案内します。</li></ul>',24))])}const b=r(g,[["render",y]]);export{T as __pageData,b as default};
